fn read_db(db_path: &Path) -> Vec<Dir> {
    // ensure parent dir exists? For query, it creates dir+file even if missing. For others, behavior differs.
    // We handle creation in callers? Simpler: here, if file doesn't exist, return empty (and caller will create on save if needed).
    // But need to handle errors for directory vs file, etc.
    // First, try to read file.
    let data = match std::fs::read(db_path) {
        Ok(d) => d,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            // check if parent is file? e.g., _ZO_DATA_DIR is file -> reading db.zo gives NotADirectory, not NotFound.
            // For NotFound, return empty (file doesn't exist). Caller will handle creation.
            return Vec::new();
        }
        Err(e) => {
            eprintln!("zoxide: could not read from database: {}\n\nCaused by:\n    {}", db_path.display(), e);
            std::process::exit(1);
        }
    };
    if data.is_empty() {
        // empty file -> corrupted data (single line)
        // Actually need to distinguish: empty file vs file with <4 bytes? All give same?
        // Observed: empty, 1 byte, 3 bytes all give "could not deserialize database: corrupted data"
        eprintln!("zoxide: could not deserialize database: corrupted data");
        std::process::exit(1);
    }
    if data.len() < 4 {
        eprintln!("zoxide: could not deserialize database: corrupted data");
        std::process::exit(1);
    }
    let version = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if version != 3 {
        eprintln!("zoxide: unsupported version (got {}, supports 3)", version);
        std::process::exit(1);
    }
    // need at least 12 bytes for version+len
    if data.len() < 12 {
        // version only or partial len -> io error unexpected end of file
        eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
        std::process::exit(1);
    }
    let n = u64::from_le_bytes([data[4], data[5], data[6], data[7], data[8], data[9], data[10], data[11]]) as usize;
    // Now parse entries. Need to replicate bincode errors exactly.
    let mut off = 12usize;
    let mut dirs = Vec::with_capacity(n.min(1000000));
    for _ in 0..n {
        // read path len u64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let len_bytes = &data[off..off+8];
        let plen = u64::from_le_bytes([len_bytes[0], len_bytes[1], len_bytes[2], len_bytes[3], len_bytes[4], len_bytes[5], len_bytes[6], len_bytes[7]]) as usize;
        off += 8;
        // read path bytes
        if off + plen > data.len() {
            // truncated path -> io error:  (empty)
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: ");
            std::process::exit(1);
        }
        let path_bytes = &data[off..off+plen];
        off += plen;
        // check utf8
        let path_str = match std::str::from_utf8(path_bytes) {
            Ok(s) => s.to_string(),
            Err(e) => {
                eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    string is not valid utf8: {}", e);
                std::process::exit(1);
            }
        };
        // read rank f64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let rank = f64::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3], data[off+4], data[off+5], data[off+6], data[off+7]]);
        off += 8;
        // read ts u64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let ts = u64::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3], data[off+4], data[off+5], data[off+6], data[off+7]]);
        off += 8;
        dirs.push(Dir { path: path_str, rank, last_accessed: ts });
    }
    if off != data.len() {
        eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    Slice had bytes remaining after deserialization");
        std::process::exit(1);
    }
    dirs
}

fn write_db(db_path: &Path, dirs: &[Dir]) {
    // ensure parent dir exists
    if let Some(parent) = db_path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            // what error? For _ZO_DATA_DIR file case, create_dir_all on file/db.zo parent which is file? Actually parent is file path itself? e.g., _ZO_DATA_DIR=/tmp/file (file), db_path=/tmp/file/db.zo, parent=/tmp/file which is file, create_dir_all fails with NotADirectory? What does original do for add with file data dir? It gave "could not read from database" on read, before write. So write error may not happen in that case because read already failed. For other cases, write could fail? Need to handle.
            eprintln!("zoxide: could not write to database: {}\n\nCaused by:\n    {}", db_path.display(), e);
            std::process::exit(1);
        }
    }
    let mut buf = Vec::new();
    buf.extend_from_slice(&3u32.to_le_bytes());
    buf.extend_from_slice(&(dirs.len() as u64).to_le_bytes());
    for d in dirs {
        let b = d.path.as_bytes();
        buf.extend_from_slice(&(b.len() as u64).to_le_bytes());
        buf.extend_from_slice(b);
        buf.extend_from_slice(&d.rank.to_le_bytes());
        buf.extend_from_slice(&d.last_accessed.to_le_bytes());
    }
    // write atomically? Original probably writes directly. Use direct write.
    // Need to handle errors: e.g., parent is file? Then write fails.
    if let Err(e) = std::fs::write(db_path, &buf) {
        // Check what error message original gives for write failures? Not probed. Assume similar to read?
        // For now, use same as read? Or generic?
        // Let's probe: _ZO_DATA_DIR as file, add should fail on read before write, so write error not reached.
        // For query with file data dir, read fails before write.
        // So write errors may be rare. Use generic.
        eprintln!("zoxide: could not write to database: {}\n\nCaused by:\n    {}", db_path.display(), e);
        std::process::exit(1);
    }
}

