fn get_exclude_patterns() -> Vec<glob::Pattern> {
    // _ZO_EXCLUDE_DIRS: colon-separated (on linux) list of globs. Default: $HOME
    // If set (even empty?), use it. If unset, use $HOME.
    // Observed: unset -> default $HOME (excludes $HOME exactly). Empty "" -> allows HOME (no patterns, since empty split gives empty? Actually "" split by ":" gives [""] -> empty pattern? But empty patterns are ignored (we saw "::" gives no error, no exclusion). So empty string should result in no patterns.
    // If set to "a:b", split by ":" (on linux, ":"; on windows ";" but we're linux).
    let raw = if let Ok(val) = std::env::var("_ZO_EXCLUDE_DIRS") {
        val
    } else {
        // default: $HOME
        if let Ok(home) = std::env::var("HOME") {
            if home.is_empty() {
                // what if HOME empty? Probably no default? Or fallback to dirs::home_dir? Let's check: with HOME empty, default exclude? Earlier HOME empty query still worked (used /home/agent for data dir, but what about exclude? Did it exclude /home/agent? We didn't test. For safety, if HOME empty, try dirs::home_dir?
                if let Some(h) = dirs::home_dir() {
                    h.to_string_lossy().to_string()
                } else {
                    String::new()
                }
            } else {
                home
            }
        } else if let Some(h) = dirs::home_dir() {
            h.to_string_lossy().to_string()
        } else {
            String::new()
        }
    };
    if raw.is_empty() {
        return Vec::new();
    }
    // split by ':' (on unix). On windows would be ';', but we're linux.
    let mut pats = Vec::new();
    for part in raw.split(':') {
        if part.is_empty() {
            continue;
        }
        match glob::Pattern::new(part) {
            Ok(p) => pats.push(p),
            Err(e) => {
                eprintln!("zoxide: invalid glob in _ZO_EXCLUDE_DIRS: {}\n\nCaused by:\n    {}", part, e);
                std::process::exit(1);
            }
        }
    }
    pats
}

fn is_excluded(path: &str, pats: &[glob::Pattern]) -> bool {
    for p in pats {
        if p.matches_with(path, glob::MatchOptions::new()) {
            return true;
        }
    }
    false
}

