fn score(rank: f64, now: u64, last: u64) -> f64 {
    let duration = now.saturating_sub(last);
    let mult = if duration < 3600 {
        4.0
    } else if duration < 86400 {
        2.0
    } else if duration < 7 * 86400 {
        0.5
    } else {
        0.25
    };
    let s = rank * mult;
    if s > 9999.0 {
        9999.0
    } else if s < 0.0 {
        0.0
    } else {
        s
    }
}

fn normalize_path(input: &str) -> String {
    // Convert to absolute + clean without resolving symlinks.
    // If relative, join with current_dir.
    // Then clean: remove ., .. (pop), empty (from //), trailing slash.
    // Preserve leading / for absolute.
    let p = Path::new(input);
    let abs: PathBuf = if p.is_absolute() {
        PathBuf::from(input)
    } else {
        match std::env::current_dir() {
            Ok(cwd) => cwd.join(p),
            Err(_) => PathBuf::from(input),
        }
    };
    // clean
    let mut comps: Vec<String> = Vec::new();
    let is_absolute = abs.is_absolute();
    for comp in abs.components() {
        match comp {
            Component::Prefix(p) => {
                // windows prefix, keep?
                comps.push(p.as_os_str().to_string_lossy().to_string());
            }
            Component::RootDir => {
                // handled by is_absolute
            }
            Component::CurDir => {
                // skip .
            }
            Component::ParentDir => {
                // pop if possible, else keep? For absolute, ignore if empty (can't go above root). For relative? But abs is absolute (since we joined cwd), so pop or ignore.
                if !comps.is_empty() {
                    comps.pop();
                }
            }
            Component::Normal(s) => {
                comps.push(s.to_string_lossy().to_string());
            }
        }
    }
    if is_absolute {
        if comps.is_empty() {
            "/".to_string()
        } else {
            format!("/{}", comps.join("/"))
        }
    } else {
        if comps.is_empty() {
            ".".to_string()
        } else {
            comps.join("/")
        }
    }
}

fn resolve_path(input: &str) -> String {
    // For _ZO_RESOLVE_SYMLINKS=1 in add: use canonicalize (resolves symlinks, requires existence).
    // Input is already checked to be dir? Add checks is_dir before? Or canonicalize first?
    // Observed: add link with resolve stores real. Add should canonicalize after checking?
    // For simplicity, try canonicalize, if fails, fallback to normalize? But add already ensures dir exists, so canonicalize should succeed.
    // Note: canonicalize returns absolute with symlinks resolved, no trailing slash.
    let p = Path::new(input);
    // Need absolute? canonicalize handles relative via cwd.
    match std::fs::canonicalize(p) {
        Ok(canon) => canon.to_string_lossy().to_string(),
        Err(_) => normalize_path(input),
    }
}

