fn read_db(db_path: &Path) -> Vec<Dir> {
    // ensure parent dir exists? For query, it creates dir+file even if missing. For others, behavior differs.
    // We handle creation in callers? Simpler: here, if file doesn't exist, return empty (and caller will create on save if needed).
