            // check if parent is file? e.g., _ZO_DATA_DIR is file -> reading db.zo gives NotADirectory, not NotFound.
            // For NotFound, return empty (file doesn't exist). Caller will handle creation.
            return Vec::new();
        }
        Err(e) => {
            eprintln!("zoxide: could not read from database: {}\n\nCaused by:\n    {}", db_path.display(), e);
            std::process::exit(1);
        }
    };
    if data.is_empty() {
        // empty file -> corrupted data (single line)
