        // Observed: empty, 1 byte, 3 bytes all give "could not deserialize database: corrupted data"
        eprintln!("zoxide: could not deserialize database: corrupted data");
        std::process::exit(1);
    }
    if data.len() < 4 {
        eprintln!("zoxide: could not deserialize database: corrupted data");
        std::process::exit(1);
    }
    let version = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if version != 3 {
        eprintln!("zoxide: unsupported version (got {}, supports 3)", version);
        std::process::exit(1);
    }
    // need at least 12 bytes for version+len
    if data.len() < 12 {
        // version only or partial len -> io error unexpected end of file
        eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
        std::process::exit(1);
    }
    let n = u64::from_le_bytes([data[4], data[5], data[6], data[7], data[8], data[9], data[10], data[11]]) as usize;
    // Now parse entries. Need to replicate bincode errors exactly.
    let mut off = 12usize;
    let mut dirs = Vec::with_capacity(n.min(1000000));
    for _ in 0..n {
        // read path len u64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let len_bytes = &data[off..off+8];
        let plen = u64::from_le_bytes([len_bytes[0], len_bytes[1], len_bytes[2], len_bytes[3], len_bytes[4], len_bytes[5], len_bytes[6], len_bytes[7]]) as usize;
        off += 8;
        // read path bytes
        if off + plen > data.len() {
            // truncated path -> io error:  (empty)
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: ");
            std::process::exit(1);
        }
        let path_bytes = &data[off..off+plen];
        off += plen;
        // check utf8
        let path_str = match std::str::from_utf8(path_bytes) {
            Ok(s) => s.to_string(),
            Err(e) => {
                eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    string is not valid utf8: {}", e);
                std::process::exit(1);
            }
        };
        // read rank f64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let rank = f64::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3], data[off+4], data[off+5], data[off+6], data[off+7]]);
        off += 8;
        // read ts u64
        if off + 8 > data.len() {
            eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    io error: unexpected end of file");
            std::process::exit(1);
        }
        let ts = u64::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3], data[off+4], data[off+5], data[off+6], data[off+7]]);
        off += 8;
        dirs.push(Dir { path: path_str, rank, last_accessed: ts });
    }
    if off != data.len() {
        eprintln!("zoxide: could not deserialize database\n\nCaused by:\n    Slice had bytes remaining after deserialization");
        std::process::exit(1);
    }
    dirs
}

