    let db_path = get_db_path(&data_dir);
    let mut existing = read_db(&db_path);
    if !existing.is_empty() && !merge {
        eprintln!("zoxide: current database is not empty, specify --merge to continue anyway");
        std::process::exit(1);
    }
    let content = match std::fs::read_to_string(&import_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("zoxide: could not open database for importing: {}\n\nCaused by:\n    {}", import_path, e);
            std::process::exit(1);
        }
    };
    let mut imported: Vec<Dir> = Vec::new();
    if from == "z" {
        for line in content.lines() {
            if line.is_empty() {
                continue;
            }
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() == 1 {
                let epoch_str = parts[0];
                match epoch_str.parse::<u64>() {
                    Ok(_) => {
                        eprintln!("zoxide: import error\n\nCaused by:\n    invalid entry: {}", line);
                        std::process::exit(1);
                    }
                    Err(e) => {
                        eprintln!("zoxide: import error\n\nCaused by:\n    0: invalid epoch: {}\n    1: {}", epoch_str, e);
                        std::process::exit(1);
                    }
                }
            } else {
                let epoch_str = parts[parts.len()-1];
                let rank_str = parts[parts.len()-2];
                let path = parts[..parts.len()-2].join("|");
                let epoch: u64 = match epoch_str.parse::<u64>() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("zoxide: import error\n\nCaused by:\n    0: invalid epoch: {}\n    1: {}", epoch_str, e);
                        std::process::exit(1);
                    }
                };
                let rank: f64 = match rank_str.parse::<f64>() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("zoxide: import error\n\nCaused by:\n    0: invalid rank: {}\n    1: {}", rank_str, e);
                        std::process::exit(1);
                    }
                };
                if let Some(entry) = imported.iter_mut().find(|d| d.path == path) {
                    entry.rank += rank;
                    if epoch > entry.last_accessed {
                        entry.last_accessed = epoch;
                    }
                } else {
                    imported.push(Dir { path, rank, last_accessed: epoch });
                }
            }
        }
    } else {
        for line in content.lines() {
            if line.is_empty() {
                continue;
            }
            match line.find('\t') {
                None => {
                    eprintln!("zoxide: import error\n\nCaused by:\n    invalid entry: {}", line);
                    std::process::exit(1);
                }
                Some(idx) => {
                    let rank_str = &line[..idx];
                    let path = line[idx+1..].to_string();
                    let rank_raw: f64 = match rank_str.parse::<f64>() {
                        Ok(v) => v,
                        Err(e) => {
                            eprintln!("zoxide: import error\n\nCaused by:\n    0: invalid rank: {}\n    1: {}", rank_str, e);
                            std::process::exit(1);
                        }
                    };
                    let rank = 1.0 / (1.0 + (-rank_raw).exp());
                    if let Some(entry) = imported.iter_mut().find(|d| d.path == path) {
                        entry.rank += rank;
                    } else {
                        imported.push(Dir { path, rank, last_accessed: 0 });
                    }
                }
            }
        }
    }
    if imported.is_empty() {
        return;
    }
    if merge {
        for imp in imported {
            if let Some(entry) = existing.iter_mut().find(|d| d.path == imp.path) {
                entry.rank += imp.rank;
                if imp.last_accessed > entry.last_accessed {
                    entry.last_accessed = imp.last_accessed;
                }
            } else {
                existing.push(imp);
            }
        }
        write_db(&db_path, &existing);
    } else {
        write_db(&db_path, &imported);
    }
}
